"""Select one authoritative executable artifact from an assistant turn."""

from dataclasses import asdict, dataclass
from typing import Optional


@dataclass(frozen=True)
class CodeArtifact:
    turn_id: int
    extraction_status: str
    selected_code: Optional[str]
    char_start: Optional[int]
    char_end: Optional[int]
    code_length: int
    block_count: int
    selection_rule: str = "last_complete_closed_python_fence"

    def to_dict(self) -> dict:
        return asdict(self)


def select_code_artifact(text: str, turn_id: int) -> CodeArtifact:
    """Keep generated bytes inside the last closed Python fence, unchanged.

    An unmatched fence is an action format error. No code is inferred from
    plain text and no missing delimiter is added.
    """
    if not isinstance(text, str):
        raise TypeError("assistant response must be text")
    blocks = []
    opened = None
    position = 0
    for line in text.splitlines(keepends=True):
        stripped = line.strip(" \t\r\n")
        if opened is None:
            if stripped.startswith("```"):
                language = stripped[3:].strip().lower()
                opened = (language, position + len(line))
        elif stripped == "```":
            language, start = opened
            if language in {"python", "py"}:
                blocks.append((start, position))
            opened = None
        position += len(line)
    if opened is not None:
        return CodeArtifact(turn_id, "ACTION_FORMAT_ERROR", None, None, None, 0, len(blocks))
    if not blocks:
        return CodeArtifact(turn_id, "NO_EXECUTABLE_CODE", None, None, None, 0, 0)
    start, end = blocks[-1]
    code = text[start:end]
    if not code.strip():
        return CodeArtifact(turn_id, "NO_EXECUTABLE_CODE", None, None, None, 0, len(blocks))
    return CodeArtifact(turn_id, "SELECTED", code, start, end, len(code), len(blocks))
